(() => {
  'use strict';

  const VERSION = 23;
  const STORAGE_KEY = 'voresCamping_clean_v22_2';
  const SECRETS_KEY = 'voresCamping_clean_secrets_v22_2';
  const ASSETS = {
    logo:'assets/logo-main.png', cover:'assets/cover-main.png', mood:'assets/corner-mood.png', hero:'assets/camp-hero.png',
    quick:{search:'assets/action-search-v18.svg',visited:'assets/action-visited-v18.svg',wish:'assets/action-wish-v18.svg',route:'assets/action-route-v18.svg',map:'assets/action-map-v18.svg',settings:'assets/action-settings-v18.svg'},
    rating:'assets/rating-star-v21.svg', markerVisited:'assets/map-visited-v21.svg', markerWish:'assets/map-wish-v21.svg', routeStart:'assets/route-start-v21.svg', routeVia:'assets/route-via-v21.svg', routeEnd:'assets/route-end-v21.svg',
    guard:{ready:'assets/ferie-vagt/ferie-vagt-ready.png',travel:'assets/ferie-vagt/ferie-vagt-travel.png',inspect:'assets/ferie-vagt/ferie-vagt-inspect.png',rest:'assets/ferie-vagt/ferie-vagt-rest.png',vacation:'assets/ferie-vagt/ferie-vagt-vacation.png'}
  };
  const MAIN_NAV = [
    ['overview','Overblik','⌂'],['visited','Besøgte','📍'],['map','Kort','🗺️'],['top','Bedst bedømte','🏆'],['wishlist','Vil besøge','💛'],['album','Ferie Album','📚'],['guard','Ferie Vagten','✨'],['settings','Indstillinger','⚙️']
  ];
  const QUICK_ACTIONS = [
    ['search','Find campingplads','search'],['addVisited','Tilføj besøg','visited'],['addWish','Tilføj ønske','wish'],['addRoute','Ny cykelrute','route'],['bigMap','Åbn stort kort','map'],['settings','Indstillinger','settings']
  ];
  const SETTINGS_TABS = [
    ['overview','Overblik'],['map','Kort'],['routeplan','Ruteplanlægning'],['campsites','Campingpladser'],['routes','Cykelruter'],['visits','Besøg'],['wishes','Ønsker'],['stars','Stjerner vurdering'],['ratings','Bedømmelse'],['guard','Ferie-Vagt'],['album','Ferie Album'],['appearance','Udseende'],['scaling','Skalering'],['sections','Sektioner'],['menu','Menu'],['boxes','Bokse'],['panels','Paneler'],['cover','Cover'],['elements','Elementer'],['clock','Ur'],['icons','Ikoner'],['illustrations','Illustrationer'],['images','Billeder'],['system','System']
  ];
  const SECTION_LABELS = {stats:'Statistik',map:'Oversigtskort',latest:'Seneste besøg',top:'Bedst bedømte',wishlist:'Ønsker',routes:'Cykelruter',mood:'Stemningsbillede'};

  let state = loadState();
  let secrets = loadSecrets();
  let weather = {summary:'Henter vejret…',location:'Aktuel placering',coords:null,fetchedAt:0,poiTips:[]};
  let mapFilter = 'all';
  let activeMapId = null;
  let routeDraft = null;
  const ors = window.VCORS?.createClient ? window.VCORS.createClient(() => ({apiKey:secrets.orsKey||'',baseUrl:secrets.orsBaseUrl||''})) : {
    geocode: async()=>({features:[]}), directions: async()=>{throw new Error('Openrouteservice kunne ikke indlæses.')},
    snap: async()=>{throw new Error('Openrouteservice kunne ikke indlæses.')}, isochrones: async()=>{throw new Error('Openrouteservice kunne ikke indlæses.')},
    matrix: async()=>{throw new Error('Openrouteservice kunne ikke indlæses.')}, pois: async()=>({features:[]}), autocomplete: async()=>({features:[]}), reverseGeocode: async()=>({features:[]}), test: async()=>false
  };

  init();

  function init(){
    applyTheme();
    window.addEventListener('hashchange', renderApp);
    document.addEventListener('click', handleGlobalClick);
    window.addEventListener('error', event => showFatal(event.error || new Error(event.message)));
    window.addEventListener('unhandledrejection', event => showFatal(event.reason instanceof Error ? event.reason : new Error(String(event.reason))));
    renderApp();
    setInterval(updateLiveDisplays,1000);
    refreshWeather();
  }

  function seedState(){
    return {
      version:VERSION,
      settings:{
        appName:'Vores Camping',tagline:'Personlig campingdagbog og overblik',greeting:'Stener & Vibses campingunivers',quote:'Vores ture, vores frihed, vores minder.',
        logo:ASSETS.logo,coverImage:ASSETS.cover,moodImage:ASSETS.mood,accent:'#1f5f3c',scale:1,compact:true,sidebarWidth:350,cardRadius:22,panelGap:16,mapStyle:'liberty',
        nextTrip:{name:'Næste campingtur',date:nextSummerDate()},clock:{showDate:true,showWeather:true,useLocation:true},
        sectionOrders:{overview:['stats','map','latest','top','wishlist','routes','mood']},
        moodPlacements:{overview:'bottom',visited:'none',map:'side',top:'bottom',wishlist:'bottom',album:'top',guard:'side'},
        menuOrder:MAIN_NAV.map(item=>item[0]),
        icons:{quick:{...ASSETS.quick},rating:ASSETS.rating,markerVisited:ASSETS.markerVisited,markerWish:ASSETS.markerWish,routeStart:ASSETS.routeStart,routeVia:ASSETS.routeVia,routeEnd:ASSETS.routeEnd},
        categories:[
          {id:'location',name:'Beliggenhed',icon:'📍'},{id:'value',name:'Pris & kvalitet',icon:'💰'},{id:'clean',name:'Renlighed',icon:'✨'},{id:'service',name:'Service',icon:'🛎️'},{id:'facilities',name:'Faciliteter',icon:'🏕️'},{id:'dogs',name:'Hundevenlig',icon:'🐾'},{id:'cycling',name:'Cykelmuligheder',icon:'🚲'}
        ],
        routeDefaults:{profile:'cycling-regular',routeType:'Rundtur',surface:'Blandet',pauseMin:20,preferScenic:true,avoidTraffic:false},
        guard:{active:false,name:'',startDate:'',holidayId:'',autoCollect:true,showTips:true,showMascot:true,mascotStyle:'auto'}
      },
      people:[
        {id:uid(),name:'Stener Sørensen',role:'Campist',kind:'person',birthDate:'1952-11-11',ownerId:'',photo:'',notes:''},
        {id:uid(),name:'Vibeke Mejlvang',nickname:'Vibse',role:'Campist',kind:'person',birthDate:'1960-03-20',ownerId:'',photo:'',notes:''},
        {id:uid(),name:'Sisi',role:'Kæledyr',kind:'pet',birthDate:'2020',ownerId:'',photo:'',notes:''}
      ],
      bikes:[],campsites:[],routes:[],holidays:[],albumItems:[],ui:{lastRoute:'overview'}
    };
  }
  function nextSummerDate(){ const d=new Date(); const year=d.getMonth()>6?d.getFullYear()+1:d.getFullYear(); return `${year}-07-15T08:00`; }
  function loadState(){
    try { const raw=localStorage.getItem(STORAGE_KEY); if(!raw) return seedState(); const parsed=JSON.parse(raw); return normalizeState(parsed); }
    catch(error){ console.error(error); return seedState(); }
  }
  function normalizeState(input){
    const fresh=seedState(); const s={...fresh,...input};
    s.version=VERSION; s.settings={...fresh.settings,...(input.settings||{})};
    s.settings.nextTrip={...fresh.settings.nextTrip,...(input.settings?.nextTrip||{})};
    s.settings.clock={...fresh.settings.clock,...(input.settings?.clock||{})};
    s.settings.icons={...fresh.settings.icons,...(input.settings?.icons||{}),quick:{...fresh.settings.icons.quick,...(input.settings?.icons?.quick||{})}};
    s.settings.sectionOrders={...fresh.settings.sectionOrders,...(input.settings?.sectionOrders||{})};
    s.settings.moodPlacements={...fresh.settings.moodPlacements,...(input.settings?.moodPlacements||{})};
    s.settings.routeDefaults={...fresh.settings.routeDefaults,...(input.settings?.routeDefaults||{})};
    s.settings.guard={...fresh.settings.guard,...(input.settings?.guard||{})};
    ['people','bikes','campsites','routes','holidays','albumItems'].forEach(k=>{if(!Array.isArray(s[k]))s[k]=[];});
    return s;
  }
  function loadSecrets(){try{return JSON.parse(localStorage.getItem(SECRETS_KEY)||'{}')}catch(_){return {}}}
  function saveState(){ state.version=VERSION; localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }
  function saveSecrets(){ localStorage.setItem(SECRETS_KEY,JSON.stringify(secrets)); }
  function applyTheme(){
    const root=document.documentElement.style; root.setProperty('--green',state.settings.accent||'#1f5f3c');root.setProperty('--scale',String(state.settings.scale||1));root.setProperty('--sidebar',`${Number(state.settings.sidebarWidth||350)}px`);root.setProperty('--radius',`${Number(state.settings.cardRadius||22)}px`);root.setProperty('--gap',`${Number(state.settings.panelGap||16)}px`);
  }

  function parseRoute(){
    const raw=(location.hash||'#overview').slice(1); const [path,q='']=raw.split('?'); const parts=path.split('/').filter(Boolean); return {name:parts[0]||'overview',id:parts[1]||'',sub:parts[2]||'',params:Object.fromEntries(new URLSearchParams(q).entries())};
  }
  function navigate(target){ location.hash=target.startsWith('#')?target:`#${target}`; }
  function renderApp(){
    try{
      clearFatal(); window.VCMaps?.destroyAll?.(); activeMapId=null;
      const route=parseRoute(); state.ui.lastRoute=route.name; saveState();
      renderTopNav(route); renderSidebar(route); renderTabletNav(route); renderHero(route);
      const view=qs('#view'); view.innerHTML='';
      if(route.name==='overview') renderOverview(view);
      else if(route.name==='visited') renderCampsiteList(view,'visited');
      else if(route.name==='wishlist') renderCampsiteList(view,'wish');
      else if(route.name==='map') renderMapPage(view);
      else if(route.name==='top') renderTopRated(view);
      else if(route.name==='album') renderAlbum(view);
      else if(route.name==='guard') renderGuard(view);
      else if(route.name==='settings') renderSettings(view,route.id||'overview');
      else if(route.name==='search') renderSearch(view);
      else if(route.name==='campsite-new') renderCampsiteForm(view,null,route.params.status||'visited');
      else if(route.name==='campsite') renderCampsiteDetail(view,route.id);
      else if(route.name==='campsite-edit') renderCampsiteForm(view,getCampsite(route.id));
      else if(route.name==='route-new') renderRouteEditor(view,null,route.params.siteId||'');
      else if(route.name==='route') renderRouteDetail(view,route.id);
      else if(route.name==='route-edit') renderRouteEditor(view,getRoute(route.id));
      else renderOverview(view);
      updateLiveDisplays();
      view.focus({preventScroll:true});
    }catch(error){showFatal(error)}
  }

  function pageMeta(route){
    const map={overview:['Vores Camping','Personlig campingdagbog og overblik'],visited:['Besøgte campingpladser','Jeres gemte campingoplevelser'],map:['Oversigtskort','Besøgte steder og ønskedestinationer'],top:['Bedst bedømte','Jeres personlige rangliste'],wishlist:['Vil besøge','Nye campingdrømme'],album:['Ferie Album','Alle feriebilleder sat i system'],guard:['Ferie Vagten','Styr på billeder, aktiviteter og minder'],settings:['Indstillinger','Alt samlet ét sted'],search:['Find campingplads','Søg online eller blandt gemte steder'],'campsite-new':['Tilføj campingplads','Opret besøg eller ønske'],'route-new':['Ny cykelrute','Planlæg en ny tur']};
    return map[route.name]||[state.settings.appName,state.settings.tagline];
  }
  function renderTopNav(route){
    const [title,subtitle]=pageMeta(route); qs('#page-title').textContent=title;qs('#page-subtitle').textContent=subtitle;
    const order=state.settings.menuOrder||MAIN_NAV.map(x=>x[0]); const map=new Map(MAIN_NAV.map(x=>[x[0],x]));
    qs('#top-nav').innerHTML=order.map(key=>map.get(key)).filter(Boolean).map(([key,label,icon])=>`<button data-nav="${key}" class="${route.name===key?'active':''}"><span>${icon}</span><span>${label}</span></button>`).join('');
  }
  function renderSidebar(route){
    const people=state.people.filter(p=>p.kind==='person').slice(0,2); const pet=state.people.find(p=>p.kind==='pet'); const c=countdownInfo();
    const guardActive=state.settings.guard.active;
    qs('#sidebar').innerHTML=`
      <section class="sidebar-card brand-card-v23"><div class="brand-logo"><img src="${state.settings.logo}" alt="Vores Camping"></div><div class="brand-copy"><span class="eyebrow">${esc(state.settings.tagline)}</span><h2>${esc(state.settings.greeting)}</h2><p>“${esc(state.settings.quote)}”</p></div><div class="family-chips">${people.map(p=>`<span class="chip">${esc(p.nickname||firstName(p.name))}</span>`).join('')}${pet?`<span class="chip">🐾 ${esc(pet.name)}</span>`:''}</div></section>
      <section class="sidebar-card"><div class="section-title"><span>Hurtig-handlinger</span><span>⚡</span></div><div class="side-actions">${QUICK_ACTIONS.map(([action,label,key])=>sideAction(action,label,key,route)).join('')}</div></section>
      <section class="sidebar-card"><div class="section-title"><span>Næste campingtur</span><span>🏕️</span></div><div class="countdown-grid">${countdownCells(c)}</div><p class="subtle small">${esc(state.settings.nextTrip.name)} · ${formatDate(state.settings.nextTrip.date)}</p></section>
      <section class="sidebar-card vacation-switch-card"><div class="vacation-switch ${guardActive?'active':''}"><div class="vacation-switch-copy"><span class="guard-live-dot"></span><div><strong>${guardActive?'Ferie-Vagten er aktiv':'Ferie-Vagten er klar'}</strong><span class="subtle small">${guardActive?'Alle nye ferieminder holdes samlet.':'Start vagten, når campingferien begynder.'}</span></div></div>${state.settings.guard.showMascot!==false?`<img class="sidebar-guard-figure" src="${guardFigure(guardActive?'ready':'vacation')}" alt="Ferie Vagten">`:''}<button class="primary-btn guard-main-button" data-toggle-guard>${guardActive?'Afslut ferie':'Start Ferie'}</button><button class="ghost-btn" data-nav="guard">Åbn Ferie Vagten</button><button class="ghost-btn" data-nav="album">Ferie Album</button></div></section>`;
  }
  function sideAction(action,label,key,route){ const icon=state.settings.icons.quick[key]||ASSETS.quick[key]; return `<button class="side-action ${quickActive(action,route)?'active':''}" data-quick="${action}"><img src="${icon}" alt=""><span><strong>${esc(label)}</strong><small>${quickDescription(action)}</small></span></button>`; }
  function quickDescription(action){return {search:'Søg efter steder',addVisited:'Registrér et besøg',addWish:'Gem en drøm',addRoute:'Planlæg på to hjul',bigMap:'Se alle markører',settings:'Tilpas hele appen'}[action]||''}
  function quickActive(action,route){return action==='search'&&route.name==='search'||action==='addVisited'&&route.name==='campsite-new'&&route.params.status!=='wish'||action==='addWish'&&route.name==='campsite-new'&&route.params.status==='wish'||action==='addRoute'&&route.name.startsWith('route')||action==='bigMap'&&route.name==='map'||action==='settings'&&route.name==='settings'}
  function renderTabletNav(route){qs('#tablet-nav').innerHTML=MAIN_NAV.slice(0,8).map(([key,label,icon])=>`<button data-nav="${key}" class="${route.name===key?'active':''}"><span>${icon}</span><span>${label}</span></button>`).join('')}

  function renderHero(route){
    const host=qs('#hero-band'); const main=['overview','visited','map','top','wishlist','album','guard'].includes(route.name); if(!main){host.innerHTML='';return}
    const tips=localTips(); const full=route.name==='overview'; const guardActive=state.settings.guard.active;
    const mascot=guardFigureForRoute(route.name);
    host.innerHTML=`<div class="hero-shell ${full?'':'compact'}" style="background-image:url('${state.settings.coverImage}')"><div class="hero-overlay"></div><div class="hero-content"><div class="hero-copy"><span class="eyebrow light">${esc(state.settings.tagline)}</span><h2>${esc(heroHeading(route))}</h2><p>${esc(heroText(route))}</p>${route.name==='overview'?`<div class="hero-actions"><button class="primary-btn guard-main-button" data-toggle-guard>${guardActive?'Ferie-Vagt aktiv':'Start Ferie'}</button><button class="secondary-btn" data-nav="album">Ferie Album</button><button class="glass-btn-v23" data-nav="guard">Se Ferie Vagten</button></div>`:''}</div>${state.settings.guard.showMascot!==false?`<div class="hero-guard-stage"><div class="guard-status-pill ${guardActive?'active':''}">${guardActive?'På vagt':'Klar til ferie'}</div><img src="${mascot}" alt="Ferie Vagten" class="hero-guard-figure"></div>`:''}<div class="hero-clock"><span class="eyebrow light">Lokal tid og vejr</span><div class="hero-time" data-live-time>--:--</div><div class="hero-date" data-live-date>Dato…</div><div class="hero-weather"><strong data-live-location>Aktuel placering</strong><span data-live-weather>Henter vejret…</span></div><button class="ghost-btn" data-refresh-weather>Opdatér</button></div><div class="hero-tips"><span class="eyebrow light">Tips i området</span><div class="tips-list">${tips.map(t=>`<div class="tip-item"><strong>${esc(t.title)}</strong><span>${esc(t.text)}</span></div>`).join('')}</div></div></div></div>`;
  }
  function guardFigure(key){ return ASSETS.guard[key] || ASSETS.guard.ready; }
  function guardFigureForRoute(routeName){
    if(routeName==='guard') return guardFigure(state.settings.guard.active?'inspect':'ready');
    if(routeName==='album') return guardFigure('rest');
    if(routeName==='map'||routeName==='visited') return guardFigure('travel');
    if(routeName==='overview') return guardFigure(state.settings.guard.active?'ready':'vacation');
    return guardFigure('inspect');
  }
  function heroHeading(route){const p=state.people.filter(x=>x.kind==='person').map(x=>x.nickname||firstName(x.name)).slice(0,2).join(' & ');return route.name==='overview'?`Velkommen tilbage, ${p||'campister'}`:pageMeta(route)[0]}
  function heroText(route){return route.name==='overview'?'Jeres campingpladser, ruter, billeder og ferieoplevelser – nu med Ferie Vagten som fast rejsemakker.':pageMeta(route)[1]}
  function localTips(){
    const attractions=state.campsites.flatMap(s=>(s.attractions||[]).map(a=>({title:a.name||'Seværdighed',text:a.description||`I nærheden af ${s.city||s.name}`}))).slice(0,2);
    const defaults=[{title:'Find en lokal oplevelse',text:'Kig efter naturstier, havne, udsigtspunkter eller markeder i nærheden.'},{title:'Gem dagens minder',text:'Føj billeder til campingpladsen, cykelruten eller Ferie Album.'},{title:'Planlæg en cykeltur',text:'Brug ruteeditoren og tilføj stop, elcykler og billeder undervejs.'}];
    return [...(weather.poiTips||[]),...attractions,...defaults].slice(0,3);
  }

  function renderOverview(view){
    const order=state.settings.sectionOrders.overview||[]; const sections={stats:overviewStats,map:overviewMap,latest:overviewLatest,top:overviewTop,wishlist:overviewWishlist,routes:overviewRoutes,mood:overviewMood};
    view.innerHTML=`<div class="view-grid">${order.map(k=>sections[k]?.()||'').join('')}</div>`;
    if(order.includes('map')) initPlaceMap('overview-map',state.campsites,{fitAll:true});
  }
  function overviewStats(){const s=stats();return `<section class="stats-grid">${statCard(s.visited,'Besøgte','✓')}${statCard(s.wish,'Ønsker','♥')}${statCard(s.countries,'Lande','🌍')}${statCard(s.routes,'Cykelruter','🚲')}</section>`}
  function overviewMap(){return `<section class="card card-section"><div class="section-head"><div><span class="eyebrow">Jeres kort</span><h2>Besøgte steder og nye drømme</h2></div><button class="ghost-btn" data-nav="map">Åbn stort kort</button></div><div id="overview-map" class="map-holder"></div></section>`}
  function overviewLatest(){const list=sortedVisited('latest').slice(0,3);return listSection('Seneste campingbesøg',list,'visited')}
  function overviewTop(){const list=sortedVisited('rating').slice(0,3);return listSection('Bedst bedømte',list,'top')}
  function overviewWishlist(){const list=state.campsites.filter(s=>s.status==='wish').slice(0,3);return listSection('Udvalgte ønsker',list,'wishlist')}
  function overviewRoutes(){const rows=state.routes.slice(0,4).map(routeRow).join('')||empty('Ingen cykelruter endnu.');return `<section class="card card-section"><div class="section-head"><div><span class="eyebrow">På to hjul</span><h3>Seneste cykelruter</h3></div><button class="ghost-btn" data-nav="route-new">Ny rute</button></div><div class="list">${rows}</div></section>`}
  function overviewMood(){return `<section class="mood-card card" style="background-image:url('${state.settings.moodImage}')"><div class="mood-copy"><h3>${esc(state.settings.quote)}</h3><p>Stener, Vibse og Sisis personlige campingdagbog.</p></div></section>`}
  function listSection(title,list,route){return `<section class="card card-section"><div class="section-head"><h3>${esc(title)}</h3><button class="ghost-btn" data-nav="${route}">Se alle</button></div><div class="list">${list.map(campsiteRow).join('')||empty('Ingen steder endnu.')}</div></section>`}

  function renderCampsiteList(view,status){
    const label=status==='visited'?'Besøgte campingpladser':'Campingpladser vi vil besøge';
    view.innerHTML=`<div class="view-grid"><section class="card card-section"><div class="section-head"><div><h2>${label}</h2><p class="subtle">Søg, filtrér og sortér.</p></div><button class="primary-btn" data-nav="campsite-new?status=${status}">Tilføj</button></div><div class="form-grid"><input id="list-search" class="field" placeholder="Søg efter navn, by, land eller tags"><select id="list-sort" class="field"><option value="latest">Seneste</option><option value="rating">Bedste vurdering</option><option value="name">Navn</option></select></div><div id="campsite-list" class="list" style="margin-top:12px"></div></section>${moodPlacement(status==='visited'?'visited':'wishlist')}</div>`;
    const update=()=>{const q=qs('#list-search').value.toLowerCase();const sort=qs('#list-sort').value;let arr=state.campsites.filter(s=>s.status===status).filter(s=>[s.name,s.city,s.country,(s.tags||[]).join(' ')].join(' ').toLowerCase().includes(q));arr=sortCampsites(arr,sort);qs('#campsite-list').innerHTML=arr.map(campsiteRow).join('')||empty('Ingen campingpladser matcher søgningen.')};
    qs('#list-search').oninput=update;qs('#list-sort').onchange=update;update();
  }

  function renderMapPage(view){
    view.innerHTML=`<div class="view-grid"><section class="card card-section"><div class="section-head"><div><h2>Oversigtskort</h2><p class="subtle">Grøn = besøgt. Gul = vil besøge.</p></div><div class="action-row"><button class="ghost-btn" id="locate-btn">Min placering</button><button class="primary-btn" data-nav="search">Find campingplads</button></div></div><div class="form-grid"><div class="segmented" id="map-filters"><button data-filter="all" class="active">Alle</button><button data-filter="visited">Besøgte</button><button data-filter="wish">Vil besøge</button></div><select id="map-style" class="field">${Object.entries(window.VCMaps.styles).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></div><div id="main-map" class="map-holder" style="margin-top:12px"></div></section>${moodPlacement('map')}</div>`;
    const draw=()=>{const places=state.campsites.filter(s=>mapFilter==='all'||s.status===mapFilter);initPlaceMap('main-map',places,{fitAll:true,styleKey:qs('#map-style').value})};
    qsa('#map-filters button').forEach(btn=>btn.onclick=()=>{mapFilter=btn.dataset.filter;qsa('#map-filters button').forEach(b=>b.classList.toggle('active',b===btn));draw()});qs('#map-style').onchange=draw;
    qs('#locate-btn').onclick=async()=>{const pos=await getCurrentPosition();if(!pos)return toast('Placering kunne ikke hentes.');const map=window.VCMaps.create('main-map',{styleKey:qs('#map-style').value,places:[...state.campsites,{id:'me',name:'Min placering',status:'visited',lng:pos.lng,lat:pos.lat}],fitAll:true,visitedIcon:state.settings.icons.markerVisited,wishIcon:state.settings.icons.markerWish});activeMapId='main-map';};
    draw();
  }

  function renderTopRated(view){
    const all=sortedVisited('rating');const podium=all.slice(0,3);const winners=state.settings.categories.map(cat=>{const sorted=[...all].sort((a,b)=>Number(b.ratings?.[cat.id]||0)-Number(a.ratings?.[cat.id]||0));return {cat,site:sorted[0]}}).filter(x=>x.site);
    view.innerHTML=`<div class="view-grid"><section class="grid-3">${podium.map((s,i)=>`<article class="card card-section"><span class="eyebrow">${['Guld','Sølv','Bronze'][i]}</span><h3>${esc(s.name)}</h3><p>${esc(countryLine(s))}</p><div class="rating">★ ${averageRating(s).toFixed(1).replace('.',',')}</div><button class="ghost-btn" data-nav="campsite/${s.id}">Se campingplads</button></article>`).join('')||empty('Ingen bedømte campingpladser endnu.')}</section><section class="card card-section"><div class="section-head"><h3>Kategorivindere</h3></div><div class="grid-3">${winners.map(w=>`<article class="card-section"><strong>${esc(w.cat.icon)} ${esc(w.cat.name)}</strong><p>${esc(w.site.name)}</p><span class="rating">${Number(w.site.ratings?.[w.cat.id]||0).toFixed(1)}</span></article>`).join('')||empty('Tilføj vurderinger for at få kategorivindere.')}</div></section>${moodPlacement('top')}</div>`;
  }

  function renderSearch(view){
    view.innerHTML=`<div class="view-grid"><section class="card card-section"><div class="section-head"><div><h2>Find campingplads</h2><p class="subtle">Openrouteservice bruges med egen API-nøgle. Uden nøgle anvendes gratis reserve-søgning.</p></div></div><div class="action-row"><input id="online-query" class="field" placeholder="Navn, by eller område" style="flex:1"><button class="primary-btn" id="online-search-btn">Søg</button></div><div id="search-results" class="list" style="margin-top:12px"></div></section></div>`;
    qs('#online-search-btn').onclick=async()=>{const q=qs('#online-query').value.trim();if(!q)return;const host=qs('#search-results');host.innerHTML=empty('Søger…');try{const features=await searchPlaces(q);host.innerHTML=features.map(searchResultRow).join('')||empty('Ingen resultater.');qsa('[data-add-result]').forEach(btn=>btn.onclick=()=>{const f=features[Number(btn.dataset.addResult)];try{sessionStorage.setItem('vc_prefill',JSON.stringify(f))}catch(_){}navigate(`campsite-new?status=${btn.dataset.status}`)});}catch(error){host.innerHTML=empty(error.message)}};
  }
  async function searchPlaces(q){
    if(secrets.orsKey){const res=await ors.geocode(q,{size:10});return (res.features||[]).map(f=>({name:f.properties?.name||f.properties?.label||q,address:f.properties?.street||'',postcode:f.properties?.postalcode||'',city:f.properties?.locality||f.properties?.region||'',region:f.properties?.region||'',country:f.properties?.country||'',lat:f.geometry?.coordinates?.[1],lng:f.geometry?.coordinates?.[0]}));}
    const res=await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=10&accept-language=da&q=${encodeURIComponent(q)}`,{headers:{'Accept':'application/json'}});if(!res.ok)throw new Error('Søgningen fejlede.');const data=await res.json();return data.map(x=>({name:x.name||x.display_name.split(',')[0],address:x.display_name,postcode:'',city:'',region:'',country:'',lat:Number(x.lat),lng:Number(x.lon)}));
  }
  function searchResultRow(r,i){return `<article class="list-row"><div style="font-size:2rem">⛺</div><div><h4>${esc(r.name)}</h4><p>${esc([r.address,r.city,r.country].filter(Boolean).join(', '))}</p></div><div class="action-row"><button class="mini-btn" data-add-result="${i}" data-status="visited">Besøgt</button><button class="mini-btn" data-add-result="${i}" data-status="wish">Ønske</button></div></article>`}

  function renderCampsiteForm(view,site,status='visited'){
    const editing=Boolean(site);const data=site?structuredClone(site):blankCampsite(status);let prefill='';try{prefill=sessionStorage.getItem('vc_prefill')||''}catch(_){}if(prefill&&!editing){try{Object.assign(data,JSON.parse(prefill))}catch(_){}try{sessionStorage.removeItem('vc_prefill')}catch(_){}}
    view.innerHTML=`<div class="view-grid"><form id="campsite-form" class="form"><section class="card form-section"><div class="section-head"><div><h2>${editing?'Redigér campingplads':'Tilføj campingplads'}</h2><p class="subtle">Alle oplysninger gemmes lokalt i browseren.</p></div></div><div class="form-grid"><label><span class="field-label">Status</span><select id="cs-status" class="field"><option value="visited" ${data.status==='visited'?'selected':''}>Besøgt</option><option value="wish" ${data.status==='wish'?'selected':''}>Vil besøge</option></select></label><label><span class="field-label">Navn</span><input id="cs-name" class="field" required value="${esc(data.name)}"></label><label><span class="field-label">Adresse</span><input id="cs-address" class="field" value="${esc(data.address)}"></label><label><span class="field-label">Postnummer</span><input id="cs-postcode" class="field" value="${esc(data.postcode)}"></label><label><span class="field-label">By</span><input id="cs-city" class="field" value="${esc(data.city)}"></label><label><span class="field-label">Region</span><input id="cs-region" class="field" value="${esc(data.region)}"></label><label><span class="field-label">Land</span><input id="cs-country" class="field" value="${esc(data.country)}"></label><label><span class="field-label">Hjemmeside</span><input id="cs-website" class="field" value="${esc(data.website)}"></label><label><span class="field-label">Telefon</span><input id="cs-phone" class="field" value="${esc(data.phone)}"></label><label><span class="field-label">Latitude</span><input id="cs-lat" class="field" value="${esc(data.lat)}"></label><label><span class="field-label">Longitude</span><input id="cs-lng" class="field" value="${esc(data.lng)}"></label></div><div class="action-row"><button type="button" class="ghost-btn" id="cs-use-location">Brug aktuel placering</button><button type="button" class="ghost-btn" data-nav="search">Søg online</button></div></section>
      <section class="card form-section"><h3>Besøg, ønsker og tekst</h3><div class="form-grid"><label><span class="field-label">Besøgsdatoer, én pr. linje</span><textarea id="cs-visits">${esc((data.visitDates||[]).join('\n'))}</textarea></label><label><span class="field-label">Planlagt dato</span><input type="date" id="cs-planned" class="field" value="${esc(data.plannedDate)}"></label></div><label><span class="field-label">Beskrivelse</span><textarea id="cs-description">${esc(data.description)}</textarea></label><label><span class="field-label">Private noter</span><textarea id="cs-notes">${esc(data.notes)}</textarea></label><label><span class="field-label">Tags, kommasepareret</span><input id="cs-tags" class="field" value="${esc((data.tags||[]).join(', '))}"></label></section>
      <section class="card form-section"><h3>Stjerner og bedømmelse</h3><div class="grid-3">${state.settings.categories.map(cat=>ratingField(cat,Number(data.ratings?.[cat.id]||0))).join('')}</div></section>
      <section class="card form-section"><h3>Billeder</h3><div class="image-drop"><input type="file" id="cs-images" multiple accept="image/*"><p>Vælg billeder fra computer, tablet eller mobil.</p></div><div id="cs-image-preview" class="image-preview-grid">${imagePreviews(data.images||[],'cs')}</div></section>
      <section class="card form-section"><h3>Seværdigheder</h3><textarea id="cs-attractions" placeholder="Navn | Beskrivelse | Link, én pr. linje">${esc((data.attractions||[]).map(a=>[a.name,a.description,a.link].join(' | ')).join('\n'))}</textarea></section>
      <div class="action-row"><button class="primary-btn" type="submit">Gem campingplads</button><button class="ghost-btn" type="button" data-nav="${editing?`campsite/${data.id}`:data.status==='wish'?'wishlist':'visited'}">Annuller</button>${editing?'<button class="danger-btn" type="button" id="delete-campsite">Slet</button>':''}</div></form></div>`;
    let images=[...(data.images||[])];bindImagePreviewRemoval('cs-image-preview',images,()=>renderPreviews());const renderPreviews=()=>{qs('#cs-image-preview').innerHTML=imagePreviews(images,'cs');bindImagePreviewRemoval('cs-image-preview',images,renderPreviews)};qs('#cs-images').onchange=async e=>{for(const file of [...e.target.files])images.push(await compressImage(file));renderPreviews()};
    qsa('[data-rating-cat]').forEach(group=>group.onclick=e=>{const btn=e.target.closest('button');if(!btn)return;group.dataset.value=btn.dataset.value;qsa('button',group).forEach(b=>b.classList.toggle('active',Number(b.dataset.value)<=Number(group.dataset.value)))});
    qs('#cs-use-location').onclick=async()=>{const p=await getCurrentPosition();if(p){qs('#cs-lat').value=p.lat;qs('#cs-lng').value=p.lng;toast('Aktuel placering indsat.')}};
    qs('#campsite-form').onsubmit=e=>{e.preventDefault();const saved=collectCampsiteForm(data,images);if(editing){const i=state.campsites.findIndex(x=>x.id===data.id);state.campsites[i]=saved}else state.campsites.push(saved);autoCollectImages(saved.images,{source:'Campingplads',title:saved.name,date:latestDate(saved),location:countryLine(saved)});saveState();toast('Campingplads gemt.');navigate(`campsite/${saved.id}`)};
    if(editing)qs('#delete-campsite').onclick=async()=>{if(await confirmAction('Slet campingplads','Campingpladsen og dens oplysninger slettes.')){state.campsites=state.campsites.filter(x=>x.id!==data.id);state.routes=state.routes.filter(r=>r.siteId!==data.id);saveState();navigate('overview')}};
  }
  function blankCampsite(status){return {id:uid(),status,name:'',address:'',postcode:'',city:'',region:'',country:'',website:'',phone:'',lat:'',lng:'',visitDates:[],plannedDate:'',description:'',notes:'',tags:[],ratings:{},images:[],attractions:[],createdAt:new Date().toISOString()}}
  function collectCampsiteForm(base,images){const ratings={};qsa('[data-rating-cat]').forEach(el=>ratings[el.dataset.ratingCat]=Number(el.dataset.value||0));return {...base,status:qs('#cs-status').value,name:qs('#cs-name').value.trim(),address:qs('#cs-address').value.trim(),postcode:qs('#cs-postcode').value.trim(),city:qs('#cs-city').value.trim(),region:qs('#cs-region').value.trim(),country:qs('#cs-country').value.trim(),website:qs('#cs-website').value.trim(),phone:qs('#cs-phone').value.trim(),lat:parseCoordinate(qs('#cs-lat').value),lng:parseCoordinate(qs('#cs-lng').value),visitDates:lines(qs('#cs-visits').value),plannedDate:qs('#cs-planned').value,description:qs('#cs-description').value.trim(),notes:qs('#cs-notes').value.trim(),tags:csv(qs('#cs-tags').value),ratings,images,attractions:parseAttractions(qs('#cs-attractions').value),updatedAt:new Date().toISOString()}}

  function renderCampsiteDetail(view,id){const site=getCampsite(id);if(!site)return navigate('overview');const routes=state.routes.filter(r=>r.siteId===id);view.innerHTML=`<div class="view-grid"><section class="card" style="overflow:hidden"><div style="min-height:310px;background:url('${site.images?.[0]||state.settings.coverImage}') center/cover;position:relative"><div class="hero-overlay"></div><div class="hero-copy" style="position:absolute;inset:auto 22px 22px;color:white"><span class="status ${site.status}">${site.status==='visited'?'Besøgt':'Vil besøge'}</span><h2>${esc(site.name)}</h2><p>${esc(countryLine(site))}</p><div class="rating">★ ${averageRating(site).toFixed(1).replace('.',',')}</div></div></div></section><section class="grid-2"><div class="card card-section"><h3>Beskrivelse og noter</h3><p>${esc(site.description||'Ingen beskrivelse endnu.')}</p><p class="subtle">${esc(site.notes||'')}</p><div class="chip-row">${(site.tags||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div></div><div class="card card-section"><h3>Vurderinger</h3><div class="table">${state.settings.categories.map(c=>`<div class="table-row"><span>${esc(c.icon)} ${esc(c.name)}</span><strong>${Number(site.ratings?.[c.id]||0).toFixed(1)}</strong><span class="rating">★★★★★</span><span></span></div>`).join('')}</div></div></section><section class="card card-section"><div class="section-head"><h3>Billeder</h3></div><div class="image-preview-grid">${(site.images||[]).map(src=>`<img src="${src}" style="width:100%;aspect-ratio:1.2;object-fit:cover;border-radius:14px">`).join('')||empty('Ingen billeder.')}</div></section><section class="grid-2"><div class="card card-section"><h3>Placering</h3><div id="detail-map" class="map-holder" style="height:330px"></div></div><div class="card card-section"><div class="section-head"><h3>Cykelruter</h3><button class="ghost-btn" data-nav="route-new?siteId=${site.id}">Ny rute</button></div><div class="list">${routes.map(routeRow).join('')||empty('Ingen ruter endnu.')}</div></div></section><section class="card card-section"><div class="section-head"><h3>Seværdigheder</h3></div><div class="list">${(site.attractions||[]).map(a=>`<div class="list-row"><div>✨</div><div><h4>${esc(a.name)}</h4><p>${esc(a.description)}</p></div>${a.link?`<a class="mini-btn" href="${safeUrl(a.link)}" target="_blank">Åbn</a>`:''}</div>`).join('')||empty('Ingen seværdigheder.')}</div></section><div class="action-row"><button class="primary-btn" data-nav="campsite-edit/${site.id}">Redigér</button>${site.lat&&site.lng?`<a class="ghost-btn" target="_blank" href="https://www.google.com/maps/search/?api=1&query=${site.lat},${site.lng}">Google Maps</a>`:''}</div></div>`;initPlaceMap('detail-map',[site],{fitAll:true})}

  function renderRouteEditor(view,existing,siteId=''){
    routeDraft=existing?structuredClone(existing):blankRoute(siteId);const r=routeDraft;
    view.innerHTML=`<div class="route-layout"><form id="route-form" class="form"><section class="card form-section"><h2>${existing?'Redigér cykelrute':'Ny cykelrute'}</h2><div class="form-grid"><label><span class="field-label">Rutenavn</span><input id="rt-name" class="field" required value="${esc(r.name)}"></label><label><span class="field-label">Dato</span><input type="date" id="rt-date" class="field" value="${esc(r.date)}"></label><label><span class="field-label">Campingplads</span><select id="rt-site" class="field"><option value="">Ingen</option>${state.campsites.map(s=>`<option value="${s.id}" ${r.siteId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label><span class="field-label">Profil</span><select id="rt-profile" class="field"><option value="cycling-regular" ${r.profile==='cycling-regular'?'selected':''}>Almindelig cykel</option><option value="cycling-electric" ${r.profile==='cycling-electric'?'selected':''}>Elcykel</option><option value="cycling-road" ${r.profile==='cycling-road'?'selected':''}>Landevej</option><option value="cycling-mountain" ${r.profile==='cycling-mountain'?'selected':''}>Mountainbike</option></select></label><label><span class="field-label">Sværhedsgrad</span><select id="rt-difficulty" class="field"><option ${r.difficulty==='Let'?'selected':''}>Let</option><option ${r.difficulty==='Mellem'?'selected':''}>Mellem</option><option ${r.difficulty==='Svær'?'selected':''}>Svær</option></select></label><label><span class="field-label">Rutetype</span><select id="rt-type" class="field"><option ${r.routeType==='Rundtur'?'selected':''}>Rundtur</option><option ${r.routeType==='Tur/retur'?'selected':''}>Tur/retur</option><option ${r.routeType==='A til B'?'selected':''}>A til B</option></select></label><label><span class="field-label">Startsted</span><input id="rt-start" class="field" value="${esc(r.start)}"></label><label><span class="field-label">Slutsted</span><input id="rt-end" class="field" value="${esc(r.end)}"></label></div><label><span class="field-label">Beskrivelse</span><textarea id="rt-description">${esc(r.description)}</textarea></label><div class="action-row"><button type="button" class="ghost-btn" id="calculate-route">Beregn med ORS</button><button type="button" class="ghost-btn" id="clear-route-points">Ryd kortpunkter</button></div><div class="stats-grid"><div class="stat-card card"><div><strong id="rt-distance">${r.distanceKm||'—'}</strong><span>km</span></div><span>↔</span></div><div class="stat-card card"><div><strong id="rt-duration">${r.durationMin||'—'}</strong><span>minutter</span></div><span>⏱</span></div><div class="stat-card card"><div><strong id="rt-ascent">${r.ascentM||'—'}</strong><span>højdemeter</span></div><span>↗</span></div><div class="stat-card card"><div><strong>${r.points.length}</strong><span>kortpunkter</span></div><span>📍</span></div></div></section>
      <section class="card form-section"><div class="section-head"><h3>Cykler på ruten</h3><button type="button" class="ghost-btn" id="add-bike-to-route">Tilføj cykel</button></div><div id="route-bikes" class="route-stops"></div></section>
      <section class="card form-section"><h3>Rutebilleder</h3><input type="file" id="rt-images" multiple accept="image/*"><div id="rt-image-preview" class="image-preview-grid">${imagePreviews(r.images,'rt')}</div></section>
      <section class="card form-section"><div class="section-head"><h3>Stop, noter og billeder</h3><button type="button" class="ghost-btn" id="add-stop-manual">Tilføj stop</button></div><div id="route-stops" class="route-stops"></div></section>
      <div class="action-row"><button class="primary-btn" type="submit">Gem rute</button><button class="ghost-btn" type="button" data-nav="${existing?`route/${r.id}`:'overview'}">Annuller</button>${existing?'<button class="danger-btn" type="button" id="delete-route">Slet</button>':''}</div></form><section class="card card-section"><div class="section-head"><div><h3>Rutens kort</h3><p class="subtle">Klik på kortet for at tilføje punkter. Første punkt er start, sidste er mål.</p></div></div><div id="route-editor-map" class="map-holder" style="height:720px"></div></section></div>`;
    let images=[...(r.images||[])];const renderImages=()=>{qs('#rt-image-preview').innerHTML=imagePreviews(images,'rt');bindImagePreviewRemoval('rt-image-preview',images,renderImages)};renderImages();qs('#rt-images').onchange=async e=>{for(const f of [...e.target.files])images.push(await compressImage(f));renderImages()};
    const renderBikes=()=>{qs('#route-bikes').innerHTML=(r.bikes||[]).map((entry,i)=>bikeEntryHtml(entry,i)).join('')||empty('Ingen cykler er tilføjet.');qsa('[data-remove-route-bike]').forEach(btn=>btn.onclick=()=>{r.bikes.splice(Number(btn.dataset.removeRouteBike),1);renderBikes()});qsa('[data-bike-select]').forEach(sel=>sel.onchange=()=>{const i=Number(sel.dataset.bikeSelect);r.bikes[i].bikeId=sel.value;renderBikes()});qsa('[data-bike-range-start]').forEach(inp=>inp.onchange=()=>r.bikes[Number(inp.dataset.bikeRangeStart)].startRangeMin=Number(inp.value));qsa('[data-bike-range-end]').forEach(inp=>inp.onchange=()=>r.bikes[Number(inp.dataset.bikeRangeEnd)].endRangeMin=Number(inp.value))};
    qs('#add-bike-to-route').onclick=()=>{r.bikes.push({bikeId:state.bikes[0]?.id||'',startRangeMin:120,endRangeMin:60});renderBikes()};renderBikes();
    const renderStops=()=>{qs('#route-stops').innerHTML=(r.stops||[]).map((stop,i)=>stopHtml(stop,i)).join('')||empty('Ingen stop endnu. Kortpunkter kan omdannes til stop.');qsa('[data-stop-label]').forEach(inp=>inp.oninput=()=>r.stops[Number(inp.dataset.stopLabel)].label=inp.value);qsa('[data-stop-note]').forEach(inp=>inp.oninput=()=>r.stops[Number(inp.dataset.stopNote)].note=inp.value);qsa('[data-remove-stop]').forEach(btn=>btn.onclick=()=>{r.stops.splice(Number(btn.dataset.removeStop),1);renderStops();drawRouteEditorMap()});qsa('[data-stop-images]').forEach(inp=>inp.onchange=async e=>{const stop=r.stops[Number(inp.dataset.stopImages)];for(const f of [...e.target.files])stop.images.push(await compressImage(f));renderStops()})};renderStops();
    qs('#add-stop-manual').onclick=()=>{r.stops.push({id:uid(),label:`Stop ${r.stops.length+1}`,lng:'',lat:'',note:'',images:[]});renderStops()};
    const drawRouteEditorMap=()=>{window.VCMaps.create('route-editor-map',{styleKey:'liberty',places:[],routeGeoJSON:r.geojson||window.VCMaps.lineFromPoints(r.points),routePoints:r.points,fitAll:true,startIcon:state.settings.icons.routeStart,viaIcon:state.settings.icons.routeVia,endIcon:state.settings.icons.routeEnd,onClick:p=>{r.points.push(p);if(r.points.length>2){const idx=r.points.length-2;if(!r.stops.some(s=>s.pointIndex===idx))r.stops.push({id:uid(),label:`Stop ${r.stops.length+1}`,lng:p.lng,lat:p.lat,pointIndex:idx,note:'',images:[]})}renderStops();drawRouteEditorMap()}});activeMapId='route-editor-map'};drawRouteEditorMap();
    qs('#clear-route-points').onclick=()=>{r.points=[];r.stops=[];r.geojson=null;renderStops();drawRouteEditorMap()};
    qs('#calculate-route').onclick=async()=>{if(r.points.length<2)return toast('Tilføj mindst start og mål på kortet.');try{setBusy(qs('#calculate-route'),true,'Beregner…');const result=await ors.directions(r.points.map(p=>[p.lng,p.lat]),qs('#rt-profile').value);r.geojson=result;const summary=result.features?.[0]?.properties?.summary||{};r.distanceKm=(Number(summary.distance||0)/1000).toFixed(1);r.durationMin=Math.round(Number(summary.duration||0)/60);r.ascentM=Math.round(Number(result.features?.[0]?.properties?.ascent||0));qs('#rt-distance').textContent=r.distanceKm;qs('#rt-duration').textContent=r.durationMin;qs('#rt-ascent').textContent=r.ascentM;drawRouteEditorMap();toast('Ruten er beregnet.')}catch(error){toast(error.message)}finally{setBusy(qs('#calculate-route'),false,'Beregn med ORS')}};
    qs('#route-form').onsubmit=e=>{e.preventDefault();Object.assign(r,{name:qs('#rt-name').value.trim()||'Ny cykelrute',date:qs('#rt-date').value,siteId:qs('#rt-site').value,profile:qs('#rt-profile').value,difficulty:qs('#rt-difficulty').value,routeType:qs('#rt-type').value,start:qs('#rt-start').value.trim(),end:qs('#rt-end').value.trim(),description:qs('#rt-description').value.trim(),images,updatedAt:new Date().toISOString()});if(existing){state.routes[state.routes.findIndex(x=>x.id===r.id)]=r}else state.routes.push(r);autoCollectImages(r.images,{source:'Cykelrute',title:r.name,date:r.date,location:`${r.start} → ${r.end}`});r.stops.forEach(s=>autoCollectImages(s.images,{source:'Rutestop',title:`${r.name} · ${s.label}`,date:r.date,location:s.label}));saveState();toast('Cykelruten er gemt.');navigate(`route/${r.id}`)};
    if(existing)qs('#delete-route').onclick=async()=>{if(await confirmAction('Slet rute','Ruten slettes permanent.')){state.routes=state.routes.filter(x=>x.id!==r.id);saveState();navigate('overview')}};
  }
  function blankRoute(siteId){const d=state.settings.routeDefaults;return {id:uid(),name:'Ny cykelrute',date:new Date().toISOString().slice(0,10),siteId,profile:d.profile,difficulty:'Let',routeType:d.routeType,start:'',end:'',description:'',points:[],stops:[],bikes:[],images:[],geojson:null,distanceKm:'',durationMin:'',ascentM:'',createdAt:new Date().toISOString()}}
  function bikeEntryHtml(entry,i){const bike=getBike(entry.bikeId);const ebike=bike?.type==='Elcykel';return `<div class="bike-card"><div class="section-head"><strong>Cykel ${i+1}</strong><button type="button" class="mini-btn" data-remove-route-bike="${i}">Fjern</button></div><select class="field" data-bike-select="${i}"><option value="">Vælg cykel</option>${state.bikes.map(b=>`<option value="${b.id}" ${entry.bikeId===b.id?'selected':''}>${esc(b.name)} · ${esc(b.type)}</option>`).join('')}</select>${ebike?`<div class="range-row"><label><span class="field-label">Rækkevidde ved start</span><select class="field" data-bike-range-start="${i}">${rangeOptions(entry.startRangeMin)}</select></label><label><span class="field-label">Rækkevidde ved slut</span><select class="field" data-bike-range-end="${i}">${rangeOptions(entry.endRangeMin)}</select></label></div>`:'<p class="subtle small">Rækkevidde vises kun for elcykler.</p>'}</div>`}
  function rangeOptions(value){return Array.from({length:61},(_,i)=>i*5).map(v=>`<option value="${v}" ${Number(value)===v?'selected':''}>${v} minutter</option>`).join('')}
  function stopHtml(stop,i){return `<div class="stop-card"><div class="section-head"><strong>Stop ${i+1}</strong><button type="button" class="mini-btn" data-remove-stop="${i}">Fjern</button></div><input class="field" data-stop-label="${i}" value="${esc(stop.label)}" placeholder="Navn"><textarea data-stop-note="${i}" placeholder="Noter">${esc(stop.note)}</textarea><input type="file" multiple accept="image/*" data-stop-images="${i}"><div class="image-preview-grid">${(stop.images||[]).map(src=>`<img src="${src}" style="width:100%;aspect-ratio:1.2;object-fit:cover;border-radius:12px">`).join('')}</div></div>`}

  function renderRouteDetail(view,id){const r=getRoute(id);if(!r)return navigate('overview');const site=getCampsite(r.siteId);view.innerHTML=`<div class="view-grid"><section class="card card-section"><div class="section-head"><div><span class="eyebrow">Cykelrute · ${formatDate(r.date)}</span><h2>${esc(r.name)}</h2><p class="subtle">${esc(site?.name||'Fritstående rute')} · ${esc(r.start||'Start')} → ${esc(r.end||'Mål')}</p></div><div class="action-row"><button class="primary-btn" data-nav="route-edit/${r.id}">Redigér</button><button class="ghost-btn" id="share-route">Del</button></div></div><div class="stats-grid">${statCard(r.distanceKm||'—','Kilometer','↔')}${statCard(r.durationMin||'—','Minutter','⏱')}${statCard(r.bikes.length,'Cykler','🚲')}${statCard(r.stops.length,'Stop','📍')}</div></section><section class="grid-2"><div class="card card-section"><h3>Beskrivelse</h3><p>${esc(r.description||'Ingen beskrivelse.')}</p><div class="table">${r.bikes.map((b,i)=>{const bike=getBike(b.bikeId);return `<div class="table-row"><span>${esc(bike?.name||`Cykel ${i+1}`)}</span><span>${esc(bike?.type||'')}</span><span>${bike?.type==='Elcykel'?`${b.startRangeMin} → ${b.endRangeMin} min`:''}</span><span></span></div>`}).join('')||empty('Ingen cykler.')}</div></div><div class="card card-section"><h3>Rutens kort</h3><div id="route-detail-map" class="map-holder" style="height:380px"></div></div></section><section class="card card-section"><h3>Rutebilleder</h3><div class="image-preview-grid">${(r.images||[]).map(src=>`<img src="${src}" style="width:100%;aspect-ratio:1.2;object-fit:cover;border-radius:14px">`).join('')||empty('Ingen billeder.')}</div></section><section class="card card-section"><h3>Stop</h3><div class="grid-3">${r.stops.map(s=>`<article class="card-section"><strong>${esc(s.label)}</strong><p class="subtle">${esc(s.note)}</p><div class="image-preview-grid">${(s.images||[]).map(src=>`<img src="${src}" style="width:100%;aspect-ratio:1.2;object-fit:cover;border-radius:12px">`).join('')}</div></article>`).join('')||empty('Ingen stop.')}</div></section></div>`;window.VCMaps.create('route-detail-map',{styleKey:'liberty',places:site?[siteToMap(site)]:[],routeGeoJSON:r.geojson||window.VCMaps.lineFromPoints(r.points),routePoints:r.points,fitAll:true,startIcon:state.settings.icons.routeStart,viaIcon:state.settings.icons.routeVia,endIcon:state.settings.icons.routeEnd});qs('#share-route').onclick=()=>shareText(`${r.name} – ${r.distanceKm||'?'} km`,location.href)}

  function renderAlbum(view){
    const items=collectAlbumItems();const holidays=state.holidays;
    view.innerHTML=`<div class="view-grid album-page-v23"><section class="card album-intro-v23"><div class="album-intro-copy"><span class="eyebrow">Ferie Album</span><h2>${items.length} minder samlet i system</h2><p class="subtle">Billeder fra campingpladser, cykelruter, rutestop og egne uploads samles automatisk under den aktive ferie.</p><div class="action-row"><button class="primary-btn" id="album-upload-btn">Tilføj billeder</button><input type="file" id="album-upload-input" multiple accept="image/*" class="hidden-file"><button class="ghost-btn" data-nav="guard">Åbn Ferie Vagten</button></div></div><img class="album-guard-figure" src="${guardFigure('rest')}" alt="Ferie Vagten holder øje med albummet"></section><section class="card card-section album-toolbar-v23"><div class="form-grid"><input id="album-search" class="field" placeholder="Søg efter ferie, sted, rute eller billedtekst"><select id="album-filter" class="field"><option value="all">Alle kilder</option><option value="Campingplads">Campingpladser</option><option value="Cykelrute">Cykelruter</option><option value="Rutestop">Rutestop</option><option value="Egen upload">Egne uploads</option></select></div><div id="album-grid" class="album-grid" style="margin-top:12px"></div></section><section class="card card-section"><div class="section-head"><div><span class="eyebrow">Feriearkiv</span><h3>Ture og albummer</h3></div><span class="album-count-pill">${holidays.length} ferier</span></div><div class="timeline">${holidays.map(h=>`<div class="timeline-day card"><strong>${esc(h.name)}</strong><span class="subtle">${formatDate(h.startDate)}${h.endDate?` – ${formatDate(h.endDate)}`:' · Aktiv'}</span></div>`).join('')||empty('Ingen afsluttede ferier endnu.')}</div></section></div>`;
    const render=()=>{const q=qs('#album-search').value.toLowerCase(),f=qs('#album-filter').value;const filtered=items.filter(i=>(f==='all'||i.source===f)&&`${i.title} ${i.location} ${i.note} ${i.source}`.toLowerCase().includes(q));qs('#album-grid').innerHTML=filtered.map(albumCard).join('')||empty('Ingen billeder matcher filtrene.')};render();qs('#album-search').oninput=render;qs('#album-filter').onchange=render;qs('#album-upload-btn').onclick=()=>qs('#album-upload-input').click();qs('#album-upload-input').onchange=async e=>{for(const file of e.target.files){state.albumItems.push({id:uid(),src:await compressImage(file,1600,.82),title:file.name.replace(/\.[^.]+$/,''),source:'Egen upload',date:new Date().toISOString().slice(0,10),location:'',note:'',holidayId:state.settings.guard.holidayId||''})}saveState();renderApp()};
  }
  function collectAlbumItems(){const items=[...state.albumItems];state.campsites.forEach(s=>(s.images||[]).forEach((src,i)=>items.push({id:`c-${s.id}-${i}`,src,title:s.name,source:'Campingplads',date:latestDate(s),location:countryLine(s),note:s.notes||''})));state.routes.forEach(r=>{(r.images||[]).forEach((src,i)=>items.push({id:`r-${r.id}-${i}`,src,title:r.name,source:'Cykelrute',date:r.date,location:`${r.start} → ${r.end}`,note:r.description||''}));(r.stops||[]).forEach((s,j)=>(s.images||[]).forEach((src,i)=>items.push({id:`s-${r.id}-${j}-${i}`,src,title:`${r.name} · ${s.label}`,source:'Rutestop',date:r.date,location:s.label,note:s.note||''}))) });return uniqueBy(items,x=>`${x.source}|${x.title}|${String(x.src).slice(0,80)}`).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
  function albumCard(item){return `<article class="album-card card"><img src="${item.src}" alt="${esc(item.title)}"><div class="album-body"><strong>${esc(item.title)}</strong><span class="subtle small">${esc(item.source)}${item.location?` · ${esc(item.location)}`:''}</span><small>${formatDate(item.date)||'Ingen dato'}</small></div></article>`}

  function renderGuard(view){
    const g=state.settings.guard;const holiday=state.holidays.find(h=>h.id===g.holidayId);const items=collectAlbumItems().filter(i=>!g.holidayId||i.holidayId===g.holidayId||!i.holidayId);
    view.innerHTML=`<div class="view-grid guard-page-v23"><section class="card guard-command-v23 ${g.active?'is-active':''}"><div class="guard-command-copy"><span class="eyebrow">Ferie Vagten</span><h2>${g.active?'Ferie-Vagten er på arbejde':'Ferie-Vagten er klar til tjeneste'}</h2><p>${g.active?`Holder styr på ${esc(holiday?.name||g.name||'ferien')} – billeder, ruter, stop og oplevelser bliver samlet.`:'Start vagten med den store ferieknap, når turen begynder.'}</p><div class="action-row"><button class="primary-btn guard-main-button" data-toggle-guard>${g.active?'Afslut og arkivér ferien':'Start Ferie'}</button><button class="ghost-btn" data-nav="album">Åbn Ferie Album</button><button class="ghost-btn" id="load-nearby-pois">Find oplevelser i nærheden</button></div></div><div class="guard-command-art"><span class="guard-shield">FERIE-VAGT</span><img src="${guardFigure(g.active?'inspect':'ready')}" alt="Ferie Vagten"></div></section><section class="stats-grid">${statCard(items.length,'Billeder','📷')}${statCard(g.active?daysSince(holiday?.startDate):0,'Feriedage','📅')}${statCard(state.routes.filter(r=>!holiday?.startDate||r.date>=holiday.startDate).length,'Ruter','🚲')}${statCard(state.campsites.filter(s=>latestDate(s)>=String(holiday?.startDate||'')).length,'Steder','⛺')}</section><section class="guard-workflow-v23"><article class="card guard-step-v23"><img src="${guardFigure('travel')}" alt="Ferie Vagten på vej"><div><span class="guard-step-number">01</span><h3>Følger turen</h3><p>Campingpladser, ruter og stop registreres under den aktive ferie.</p></div></article><article class="card guard-step-v23"><img src="${guardFigure('inspect')}" alt="Ferie Vagten kontrollerer"><div><span class="guard-step-number">02</span><h3>Holder orden</h3><p>Nye billeder får kilde, dato, sted og ferie tilknyttet automatisk.</p></div></article><article class="card guard-step-v23"><img src="${guardFigure('vacation')}" alt="Ferie Vagten slapper af"><div><span class="guard-step-number">03</span><h3>Samler minderne</h3><p>Når ferien afsluttes, ligger det hele klar i Ferie Album.</p></div></article></section><section class="grid-2 guard-lower-grid-v23"><div class="card card-section"><div class="section-head"><div><span class="eyebrow">Kontroltavle</span><h3>Automatisk opsamling</h3></div><span class="status ${g.active?'visited':'wish'}">${g.active?'Aktiv':'Klar'}</span></div><div class="table"><div class="table-row"><span>Campingpladsbilleder</span><strong>Samles</strong><span>✓</span><span></span></div><div class="table-row"><span>Rutebilleder</span><strong>Samles</strong><span>✓</span><span></span></div><div class="table-row"><span>Billeder ved stop</span><strong>Samles</strong><span>✓</span><span></span></div><div class="table-row"><span>Egne uploads</span><strong>Samles</strong><span>✓</span><span></span></div></div></div><div class="card card-section"><div class="section-head"><div><span class="eyebrow">Området omkring jer</span><h3>Tips og forslag</h3></div></div><div class="tips-list guard-tip-list" id="guard-nearby-tips">${localTips().map(t=>`<div class="tip-item"><strong>${esc(t.title)}</strong><span>${esc(t.text)}</span></div>`).join('')}</div></div></section><section class="card card-section"><div class="section-head"><div><span class="eyebrow">Aktivt feriealbum</span><h3>Seneste billeder</h3></div><button class="ghost-btn" data-nav="album">Se hele albummet</button></div><div class="album-grid">${items.slice(0,8).map(albumCard).join('')||empty('Ingen billeder endnu.')}</div></section></div>`;
    const poiButton=qs('#load-nearby-pois');if(poiButton)poiButton.onclick=loadNearbyPois;
  }

  async function loadNearbyPois(){
    const host=qs('#guard-nearby-tips');const btn=qs('#load-nearby-pois');if(!host||!btn)return;
    const coords=weather.coords||await getCurrentPosition();if(!coords){toast('Placeringen kunne ikke hentes.');return;}
    try{setBusy(btn,true,'Finder oplevelser…');const delta=.08;const result=await ors.pois({bbox:[[coords.lng-delta,coords.lat-delta],[coords.lng+delta,coords.lat+delta]]},{limit:10});const features=result?.features||result?.pois||[];const tips=features.slice(0,6).map(feature=>({title:feature.properties?.osm_tags?.name||feature.properties?.name||'Lokal oplevelse',text:feature.properties?.category_name||feature.properties?.osm_tags?.tourism||'I nærheden af jeres placering'}));weather.poiTips=tips;if(tips.length)host.innerHTML=tips.map(t=>`<div class="tip-item"><strong>${esc(t.title)}</strong><span>${esc(t.text)}</span></div>`).join('');else toast('Der blev ikke fundet forslag i nærheden.');}
    catch(error){toast(error.message||'Lokale forslag kunne ikke hentes.');}
    finally{setBusy(btn,false,'Find oplevelser i nærheden');}
  }
  async function toggleGuard(){const g=state.settings.guard;if(!g.active){const name=prompt('Hvad skal ferien hedde?',state.settings.nextTrip.name||'Campingferie')||'Campingferie';const h={id:uid(),name,startDate:new Date().toISOString().slice(0,10),endDate:'',createdAt:new Date().toISOString()};state.holidays.push(h);Object.assign(g,{active:true,name,holidayId:h.id,startDate:h.startDate})}else{const h=state.holidays.find(x=>x.id===g.holidayId);if(h)h.endDate=new Date().toISOString().slice(0,10);Object.assign(g,{active:false,name:'',holidayId:'',startDate:''})}saveState();toast(g.active?'Ferie-Vagten er startet.':'Ferien er afsluttet og gemt i albummet.');renderApp()}
  function autoCollectImages(images,meta){if(!state.settings.guard.active||!state.settings.guard.autoCollect)return;(images||[]).forEach(src=>{if(state.albumItems.some(i=>i.src===src))return;state.albumItems.push({id:uid(),src,title:meta.title||'Feriebillede',source:meta.source||'App',date:meta.date||new Date().toISOString().slice(0,10),location:meta.location||'',note:meta.note||'',holidayId:state.settings.guard.holidayId||''})})}

  function renderSettings(view,tab){
    const active=SETTINGS_TABS.some(x=>x[0]===tab)?tab:'overview';view.innerHTML=`<div class="settings-shell"><aside class="settings-nav card">${SETTINGS_TABS.map(([id,label])=>`<button data-nav="settings/${id}" class="${active===id?'active':''}">${esc(label)}</button>`).join('')}</aside><section id="settings-content" class="settings-content">${settingsPanel(active)}</section></div>`;bindSettings(active);
  }
  function settingsPanel(tab){
    if(tab==='overview')return `<div class="view-grid"><section class="card form-section"><h2>Overblik</h2><label><span class="field-label">Appnavn</span><input id="set-appname" class="field" value="${esc(state.settings.appName)}"></label><label><span class="field-label">Hilsen</span><input id="set-greeting" class="field" value="${esc(state.settings.greeting)}"></label><label><span class="field-label">Citat</span><input id="set-quote" class="field" value="${esc(state.settings.quote)}"></label><button class="primary-btn" id="save-overview-settings">Gem</button></section></div>`;
    if(tab==='map')return `<div class="view-grid"><section class="card form-section"><h2>Kort</h2><label><span class="field-label">Standard kortstil</span><select id="set-map-style" class="field">${Object.entries(window.VCMaps.styles).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}</select></label><p class="subtle">Markører og ikoner kan ændres under Ikoner.</p></section></div>`;
    if(tab==='routeplan')return `<div class="view-grid"><section class="card form-section ors-settings-v23"><div class="section-head"><div><span class="eyebrow">Openrouteservice v23</span><h2>Ruteplanlægning og udvidelser</h2></div><span class="ors-version-pill">12 funktioner</span></div><label><span class="field-label">Openrouteservice API-nøgle</span><input id="set-ors-key" class="field" value="${esc(secrets.orsKey||'')}"></label><label><span class="field-label">ORS base-URL</span><input id="set-ors-base" class="field" value="${esc(secrets.orsBaseUrl||'https://api.openrouteservice.org')}"></label><div class="ors-capability-grid">${['Autocomplete','Geokodning','Reverse geokodning','Rute GeoJSON','GPX','Snap til vej','Isokroner','Matrix','POI','Højdedata','Optimering','Elcykel'].map(x=>`<span>${x}</span>`).join('')}</div><div class="action-row"><button class="primary-btn" id="save-ors">Gem</button><button class="ghost-btn" id="test-ors">Test forbindelse</button><a class="ghost-btn" href="resources/openrouteservice-extensions-v23.zip" download>Download ORS-udvidelser</a></div></section></div>`;
    if(tab==='campsites')return settingsSummary('Campingpladser',state.campsites.map(campsiteRow).join('')||empty('Ingen campingpladser.'));
    if(tab==='routes')return settingsSummary('Cykelruter',state.routes.map(routeRow).join('')||empty('Ingen ruter.'));
    if(tab==='visits')return settingsSummary('Besøg',state.campsites.filter(s=>s.status==='visited').map(campsiteRow).join('')||empty('Ingen besøg.'));
    if(tab==='wishes')return settingsSummary('Ønsker',state.campsites.filter(s=>s.status==='wish').map(campsiteRow).join('')||empty('Ingen ønsker.'));
    if(tab==='stars')return categorySettings('Stjerner vurdering');
    if(tab==='ratings')return categorySettings('Bedømmelse');
    if(tab==='guard'){const g=state.settings.guard;return `<div class="view-grid"><section class="card guard-settings-v23"><div class="guard-settings-art"><img src="${guardFigure(g.active?'inspect':'ready')}" alt="Ferie Vagten"></div><div class="form-section"><span class="eyebrow">Ferie Vagten</span><h2>Design og automatik</h2><label class="check-row"><input type="checkbox" id="set-guard-auto" ${g.autoCollect?'checked':''}> Saml billeder automatisk</label><label class="check-row"><input type="checkbox" id="set-guard-tips" ${g.showTips?'checked':''}> Vis lokale tips</label><label class="check-row"><input type="checkbox" id="set-guard-mascot" ${g.showMascot!==false?'checked':''}> Vis Ferie-Vagt-figuren i appens design</label><div class="action-row"><button class="primary-btn" id="save-guard-settings">Gem</button><button class="ghost-btn" data-nav="guard">Åbn Ferie Vagten</button></div></div></section></div>`}
    if(tab==='album')return `<div class="view-grid"><section class="card form-section"><h2>Ferie Album</h2><p class="subtle">${collectAlbumItems().length} billeder er samlet.</p><button class="primary-btn" data-nav="album">Åbn Ferie Album</button></section></div>`;
    if(tab==='appearance')return `<div class="view-grid"><section class="card form-section"><h2>Udseende</h2><label><span class="field-label">Primær farve</span><input type="color" id="set-accent" value="${state.settings.accent}"></label><label class="check-row"><input type="checkbox" id="set-compact" ${state.settings.compact?'checked':''}> Kompakt layout</label><button class="primary-btn" id="save-appearance">Gem</button></section></div>`;
    if(tab==='scaling')return `<div class="view-grid"><section class="card form-section"><h2>Skalering</h2><label><span class="field-label">Tekst og elementer</span><input type="range" id="set-scale" min=".88" max="1.18" step=".01" value="${state.settings.scale}"></label><label><span class="field-label">Venstremenu, px</span><input type="range" id="set-sidebar-width" min="310" max="430" step="5" value="${state.settings.sidebarWidth}"></label><button class="primary-btn" id="save-scaling">Gem</button></section></div>`;
    if(tab==='sections')return sectionOrderSettings();
    if(tab==='menu')return menuOrderSettings();
    if(tab==='boxes')return radiusSettings('Bokse');
    if(tab==='panels')return radiusSettings('Paneler');
    if(tab==='cover')return imageSetting('Cover',state.settings.coverImage,'cover');
    if(tab==='elements')return peopleAndBikesSettings();
    if(tab==='clock')return `<div class="view-grid"><section class="card form-section"><h2>Ur</h2><label><span class="field-label">Næste tur</span><input id="set-trip-name" class="field" value="${esc(state.settings.nextTrip.name)}"></label><label><span class="field-label">Dato og tid</span><input type="datetime-local" id="set-trip-date" class="field" value="${toLocalInput(state.settings.nextTrip.date)}"></label><label class="check-row"><input type="checkbox" id="set-show-weather" ${state.settings.clock.showWeather?'checked':''}> Vis vejr</label><button class="primary-btn" id="save-clock">Gem</button></section></div>`;
    if(tab==='icons')return iconSettings();
    if(tab==='illustrations')return imageSetting('Illustrationer',state.settings.moodImage,'mood');
    if(tab==='images')return `<div class="view-grid"><section class="card form-section"><h2>Billeder</h2><p class="subtle">Billeder komprimeres automatisk før lokal lagring.</p><button class="ghost-btn" data-nav="album">Administrér billeder i Ferie Album</button></section></div>`;
    if(tab==='system')return systemSettings();
    return settingsSummary('Indstillinger',empty('Ingen indstillinger på denne side.'));
  }
  function settingsSummary(title,html){return `<div class="view-grid"><section class="card card-section"><div class="section-head"><h2>${esc(title)}</h2></div><div class="list">${html}</div></section></div>`}
  function categorySettings(title){return `<div class="view-grid"><section class="card form-section"><h2>${title}</h2><div id="category-list" class="table">${state.settings.categories.map((c,i)=>`<div class="table-row"><input class="field" data-cat-name="${i}" value="${esc(c.name)}"><input class="field" data-cat-icon="${i}" value="${esc(c.icon)}"><span></span><button class="mini-btn" data-remove-cat="${i}">Fjern</button></div>`).join('')}</div><div class="action-row"><button class="ghost-btn" id="add-category">Tilføj kategori</button><button class="primary-btn" id="save-categories">Gem</button></div></section></div>`}
  function sectionOrderSettings(){const order=state.settings.sectionOrders.overview;return `<div class="view-grid"><section class="card form-section"><h2>Sektioner</h2><p class="subtle">Flyt sektionerne op eller ned på forsiden.</p><div class="table">${order.map((id,i)=>`<div class="table-row drag-row"><strong>${esc(SECTION_LABELS[id]||id)}</strong><span></span><button class="mini-btn" data-section-up="${i}">Op</button><button class="mini-btn" data-section-down="${i}">Ned</button></div>`).join('')}</div><label><span class="field-label">Stemningsbillede på forsiden</span><select id="set-mood-overview" class="field"><option value="top">Øverst</option><option value="bottom" ${state.settings.moodPlacements.overview==='bottom'?'selected':''}>Nederst</option><option value="none" ${state.settings.moodPlacements.overview==='none'?'selected':''}>Skjult</option></select></label></section></div>`}
  function menuOrderSettings(){const order=state.settings.menuOrder;const map=new Map(MAIN_NAV.map(x=>[x[0],x]));return `<div class="view-grid"><section class="card form-section"><h2>Menu</h2><div class="table">${order.map((id,i)=>`<div class="table-row"><strong>${esc(map.get(id)?.[1]||id)}</strong><span></span><button class="mini-btn" data-menu-up="${i}">Op</button><button class="mini-btn" data-menu-down="${i}">Ned</button></div>`).join('')}</div></section></div>`}
  function radiusSettings(title){return `<div class="view-grid"><section class="card form-section"><h2>${title}</h2><label><span class="field-label">Afrunding</span><input type="range" id="set-radius" min="8" max="34" value="${state.settings.cardRadius}"></label><label><span class="field-label">Afstand mellem paneler</span><input type="range" id="set-gap" min="8" max="28" value="${state.settings.panelGap}"></label><button class="primary-btn" id="save-radius">Gem</button></section></div>`}
  function imageSetting(title,src,type){return `<div class="view-grid"><section class="card form-section"><h2>${title}</h2><div class="image-drop"><img src="${src}" style="max-height:260px;margin:auto;object-fit:contain"><input type="file" id="upload-${type}" accept="image/*"></div><button class="primary-btn" id="save-${type}-image">Gem billede</button></section></div>`}
  function peopleAndBikesSettings(){return `<div class="view-grid"><section class="card form-section"><div class="section-head"><h2>Personer og dyr</h2><button class="ghost-btn" id="add-person">Opret</button></div><div class="table">${state.people.map((p,i)=>`<div class="table-row"><span>${esc(p.name)}</span><span>${esc(p.role)}</span><span>${esc(p.kind==='pet'?'Dyr':'Person')}</span><button class="mini-btn" data-edit-person="${i}">Redigér</button></div>`).join('')}</div><div id="person-editor"></div></section><section class="card form-section"><div class="section-head"><h2>Cykler</h2><button class="ghost-btn" id="add-bike">Opret</button></div><div class="table">${state.bikes.map((b,i)=>`<div class="table-row"><span>${esc(b.name)}</span><span>${esc(b.type)}</span><span>${esc(getPerson(b.ownerId)?.name||'Ingen ejer')}</span><button class="mini-btn" data-edit-bike="${i}">Redigér</button></div>`).join('')||empty('Ingen cykler oprettet.')}</div><div id="bike-editor"></div></section></div>`}
  function iconSettings(){const items=[...QUICK_ACTIONS.map(([a,l,k])=>[`quick.${k}`,l,state.settings.icons.quick[k]]),['rating','Stjerne',state.settings.icons.rating],['markerVisited','Besøgt markør',state.settings.icons.markerVisited],['markerWish','Ønske markør',state.settings.icons.markerWish],['routeStart','Rutestart',state.settings.icons.routeStart],['routeVia','Rutestop',state.settings.icons.routeVia],['routeEnd','Rutemål',state.settings.icons.routeEnd]];return `<div class="view-grid"><section class="card form-section"><h2>Ikoner</h2><div class="icon-config-grid">${items.map(([key,label,src])=>`<div class="icon-config"><img src="${src}" alt=""><strong>${esc(label)}</strong><input type="file" accept="image/*,.svg" data-icon-upload="${key}"></div>`).join('')}</div></section></div>`}
  function systemSettings(){return `<div class="view-grid"><section class="card form-section"><h2>System</h2><div class="panel">Version ${VERSION}. Ferie-Vagt-figurer og Openrouteservice-udvidelser er integreret i denne finpudsede version.</div><div class="action-row"><button class="primary-btn" id="export-backup">Eksportér backup</button><button class="ghost-btn" id="import-backup">Importér backup</button><input type="file" id="import-backup-file" accept="application/json" class="hidden-file"><button class="danger-btn" id="reset-app">Nulstil den nye app</button></div></section></div>`}

  function bindSettings(tab){
    if(tab==='overview')qs('#save-overview-settings').onclick=()=>{state.settings.appName=qs('#set-appname').value.trim();state.settings.greeting=qs('#set-greeting').value.trim();state.settings.quote=qs('#set-quote').value.trim();saveState();renderApp()};
    if(tab==='map'){const sel=qs('#set-map-style');if(sel){sel.value=state.settings.mapStyle||'liberty';sel.onchange=()=>{state.settings.mapStyle=sel.value;saveState();toast('Kortstil gemt.')}}}
    if(tab==='routeplan'){qs('#save-ors').onclick=()=>{secrets.orsKey=qs('#set-ors-key').value.trim();secrets.orsBaseUrl=qs('#set-ors-base').value.trim();saveSecrets();toast('ORS-indstillinger gemt.')};qs('#test-ors').onclick=async()=>{try{setBusy(qs('#test-ors'),true,'Tester…');toast(await ors.test()?'Forbindelsen virker.':'Ingen svar.')}catch(e){toast(e.message)}finally{setBusy(qs('#test-ors'),false,'Test forbindelse')}}}
    if(tab==='stars'||tab==='ratings'){qs('#add-category').onclick=()=>{state.settings.categories.push({id:uid(),name:'Ny kategori',icon:'⭐'});saveState();renderApp()};qsa('[data-remove-cat]').forEach(b=>b.onclick=()=>{state.settings.categories.splice(Number(b.dataset.removeCat),1);saveState();renderApp()});qs('#save-categories').onclick=()=>{qsa('[data-cat-name]').forEach(i=>state.settings.categories[Number(i.dataset.catName)].name=i.value.trim());qsa('[data-cat-icon]').forEach(i=>state.settings.categories[Number(i.dataset.catIcon)].icon=i.value.trim());saveState();toast('Kategorier gemt.')}}
    if(tab==='guard')qs('#save-guard-settings').onclick=()=>{state.settings.guard.autoCollect=qs('#set-guard-auto').checked;state.settings.guard.showTips=qs('#set-guard-tips').checked;state.settings.guard.showMascot=qs('#set-guard-mascot').checked;saveState();toast('Ferie-Vagt gemt.');renderApp()};
    if(tab==='appearance')qs('#save-appearance').onclick=()=>{state.settings.accent=qs('#set-accent').value;state.settings.compact=qs('#set-compact').checked;saveState();applyTheme();renderApp()};
    if(tab==='scaling')qs('#save-scaling').onclick=()=>{state.settings.scale=Number(qs('#set-scale').value);state.settings.sidebarWidth=Number(qs('#set-sidebar-width').value);saveState();applyTheme();renderApp()};
    if(tab==='sections'){qsa('[data-section-up]').forEach(b=>b.onclick=()=>moveItem(state.settings.sectionOrders.overview,Number(b.dataset.sectionUp),-1));qsa('[data-section-down]').forEach(b=>b.onclick=()=>moveItem(state.settings.sectionOrders.overview,Number(b.dataset.sectionDown),1));qs('#set-mood-overview').onchange=()=>{state.settings.moodPlacements.overview=qs('#set-mood-overview').value;saveState()}}
    if(tab==='menu'){qsa('[data-menu-up]').forEach(b=>b.onclick=()=>moveItem(state.settings.menuOrder,Number(b.dataset.menuUp),-1));qsa('[data-menu-down]').forEach(b=>b.onclick=()=>moveItem(state.settings.menuOrder,Number(b.dataset.menuDown),1))}
    if(tab==='boxes'||tab==='panels')qs('#save-radius').onclick=()=>{state.settings.cardRadius=Number(qs('#set-radius').value);state.settings.panelGap=Number(qs('#set-gap').value);saveState();applyTheme();renderApp()};
    if(tab==='cover')bindSingleImageSetting('cover',src=>state.settings.coverImage=src);
    if(tab==='illustrations')bindSingleImageSetting('mood',src=>state.settings.moodImage=src);
    if(tab==='clock')qs('#save-clock').onclick=()=>{state.settings.nextTrip.name=qs('#set-trip-name').value.trim();state.settings.nextTrip.date=qs('#set-trip-date').value;state.settings.clock.showWeather=qs('#set-show-weather').checked;saveState();renderApp()};
    if(tab==='elements')bindPeopleBikes();
    if(tab==='icons')qsa('[data-icon-upload]').forEach(input=>input.onchange=async e=>{const file=e.target.files[0];if(!file)return;const src=file.type.includes('svg')?await file.text().then(t=>'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(t)))):await compressImage(file,256,.9);setIconPath(input.dataset.iconUpload,src);saveState();renderApp()});
    if(tab==='system'){qs('#export-backup').onclick=exportBackup;qs('#import-backup').onclick=()=>qs('#import-backup-file').click();qs('#import-backup-file').onchange=importBackup;qs('#reset-app').onclick=async()=>{if(await confirmAction('Nulstil app','Alle data i denne nye version slettes.')){localStorage.removeItem(STORAGE_KEY);state=seedState();saveState();renderApp()}}}
  }
  function bindSingleImageSetting(type,setter){let value='';qs(`#upload-${type}`).onchange=async e=>{value=await compressImage(e.target.files[0],1800,.84);toast('Billedet er klar til at blive gemt.')};qs(`#save-${type}-image`).onclick=()=>{if(value)setter(value);saveState();renderApp()}}
  function bindPeopleBikes(){
    const renderPersonEditor=i=>{const p=i===null?{id:uid(),name:'',nickname:'',role:'Campist',kind:'person',birthDate:'',ownerId:'',photo:'',notes:''}:{...state.people[i]};qs('#person-editor').innerHTML=`<div class="form-section"><h3>${i===null?'Ny person eller dyr':'Redigér'}</h3><div class="form-grid"><input id="pe-name" class="field" placeholder="Navn" value="${esc(p.name)}"><input id="pe-nick" class="field" placeholder="Kælenavn" value="${esc(p.nickname||'')}"><select id="pe-kind" class="field"><option value="person" ${p.kind==='person'?'selected':''}>Person</option><option value="pet" ${p.kind==='pet'?'selected':''}>Dyr</option></select><select id="pe-role" class="field">${['Campist','Familie','Gæst/besøgende','Campist på campingplads','Kæledyr','Kæledyrsejer'].map(x=>`<option ${p.role===x?'selected':''}>${x}</option>`).join('')}</select><input id="pe-birth" class="field" placeholder="Fødselsdato eller år" value="${esc(p.birthDate||'')}"><select id="pe-owner" class="field"><option value="">Ingen ejer</option>${state.people.filter(x=>x.kind==='person').map(x=>`<option value="${x.id}" ${p.ownerId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><textarea id="pe-notes" placeholder="Noter">${esc(p.notes||'')}</textarea><div class="action-row"><button class="primary-btn" id="save-person-editor">Gem</button>${i!==null?'<button class="danger-btn" id="delete-person-editor">Slet</button>':''}</div></div>`;qs('#save-person-editor').onclick=()=>{Object.assign(p,{name:qs('#pe-name').value.trim(),nickname:qs('#pe-nick').value.trim(),kind:qs('#pe-kind').value,role:qs('#pe-role').value,birthDate:qs('#pe-birth').value.trim(),ownerId:qs('#pe-owner').value,notes:qs('#pe-notes').value.trim()});if(i===null)state.people.push(p);else state.people[i]=p;saveState();renderApp()};if(i!==null)qs('#delete-person-editor').onclick=()=>{state.people.splice(i,1);saveState();renderApp()}};
    qs('#add-person').onclick=()=>renderPersonEditor(null);qsa('[data-edit-person]').forEach(b=>b.onclick=()=>renderPersonEditor(Number(b.dataset.editPerson)));
    const renderBikeEditor=i=>{const b=i===null?{id:uid(),name:'',type:'Almindelig cykel',ownerId:'',notes:''}:{...state.bikes[i]};qs('#bike-editor').innerHTML=`<div class="form-section"><h3>${i===null?'Ny cykel':'Redigér cykel'}</h3><div class="form-grid"><input id="be-name" class="field" placeholder="Cykelnavn" value="${esc(b.name)}"><select id="be-type" class="field"><option ${b.type==='Almindelig cykel'?'selected':''}>Almindelig cykel</option><option ${b.type==='Elcykel'?'selected':''}>Elcykel</option><option ${b.type==='Landevejscykel'?'selected':''}>Landevejscykel</option><option ${b.type==='Mountainbike'?'selected':''}>Mountainbike</option></select><select id="be-owner" class="field"><option value="">Ingen ejer</option>${state.people.filter(x=>x.kind==='person').map(x=>`<option value="${x.id}" ${b.ownerId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><textarea id="be-notes">${esc(b.notes||'')}</textarea><div class="action-row"><button class="primary-btn" id="save-bike-editor">Gem</button>${i!==null?'<button class="danger-btn" id="delete-bike-editor">Slet</button>':''}</div></div>`;qs('#save-bike-editor').onclick=()=>{Object.assign(b,{name:qs('#be-name').value.trim(),type:qs('#be-type').value,ownerId:qs('#be-owner').value,notes:qs('#be-notes').value.trim()});if(i===null)state.bikes.push(b);else state.bikes[i]=b;saveState();renderApp()};if(i!==null)qs('#delete-bike-editor').onclick=()=>{state.bikes.splice(i,1);saveState();renderApp()}};
    qs('#add-bike').onclick=()=>renderBikeEditor(null);qsa('[data-edit-bike]').forEach(b=>b.onclick=()=>renderBikeEditor(Number(b.dataset.editBike)));
  }

  function handleGlobalClick(e){
    const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}
    const quick=e.target.closest('[data-quick]');if(quick){const routes={search:'search',addVisited:'campsite-new?status=visited',addWish:'campsite-new?status=wish',addRoute:'route-new',bigMap:'map',settings:'settings/overview'};navigate(routes[quick.dataset.quick]);return}
    if(e.target.closest('[data-toggle-guard]')){toggleGuard();return}
    if(e.target.closest('[data-refresh-weather]')){refreshWeather(true);return}
    const open=e.target.closest('[data-open-place]');if(open?.dataset.openPlace)navigate(`campsite/${open.dataset.openPlace}`);
  }

  function initPlaceMap(id,places,opts={}){activeMapId=id;if(!window.VCMaps?.create){const el=qs('#'+id);if(el)el.innerHTML='<div class="map-fallback">Kortmotoren er ikke tilgængelig, men resten af appen virker.</div>';return null;}window.VCMaps.create(id,{styleKey:opts.styleKey||state.settings.mapStyle||'liberty',places:places.map(siteToMap),fitAll:opts.fitAll!==false,visitedIcon:state.settings.icons.markerVisited,wishIcon:state.settings.icons.markerWish})}
  function siteToMap(s){return {id:s.id,name:s.name,city:s.city,country:s.country,status:s.status,lng:Number(s.lng),lat:Number(s.lat)}}
  function statCard(value,label,icon){return `<article class="stat-card card"><div><strong>${value}</strong><span>${esc(label)}</span></div><div class="stat-icon">${icon}</div></article>`}
  function campsiteRow(s){return `<article class="list-row"><img src="${s.images?.[0]||state.settings.coverImage}" alt=""><div><h4>${esc(s.name||'Uden navn')}</h4><p>${esc(countryLine(s))}</p><span class="status ${s.status}">${s.status==='visited'?'Besøgt':'Vil besøge'}</span> <span class="rating">★ ${averageRating(s).toFixed(1).replace('.',',')}</span></div><button class="mini-btn" data-nav="campsite/${s.id}">Detaljer</button></article>`}
  function routeRow(r){return `<article class="list-row"><div style="font-size:2rem">🚲</div><div><h4>${esc(r.name)}</h4><p>${formatDate(r.date)} · ${esc(r.start||'Start')} → ${esc(r.end||'Mål')} · ${r.distanceKm||'—'} km</p></div><button class="mini-btn" data-nav="route/${r.id}">Åbn</button></article>`}
  function ratingField(cat,value){return `<div><span class="field-label">${esc(cat.icon)} ${esc(cat.name)}</span><div class="segmented" data-rating-cat="${cat.id}" data-value="${value}">${[1,2,3,4,5].map(v=>`<button type="button" data-value="${v}" class="${v<=value?'active':''}">★</button>`).join('')}</div></div>`}
  function imagePreviews(images,prefix){return images.map((src,i)=>`<div class="image-preview"><img src="${src}"><button type="button" data-remove-preview="${i}" data-prefix="${prefix}">×</button></div>`).join('')}
  function bindImagePreviewRemoval(hostId,images,render){qsa(`#${hostId} [data-remove-preview]`).forEach(btn=>btn.onclick=()=>{images.splice(Number(btn.dataset.removePreview),1);render()})}
  function moodPlacement(page){return state.settings.moodPlacements[page]==='none'?'':`<section class="mood-card card" style="background-image:url('${state.settings.moodImage}')"><div class="mood-copy"><h3>${esc(state.settings.quote)}</h3></div></section>`}
  function countdownInfo(){const target=new Date(state.settings.nextTrip.date||Date.now());const diff=Math.max(0,target-Date.now());return {days:Math.floor(diff/86400000),hours:Math.floor(diff%86400000/3600000),minutes:Math.floor(diff%3600000/60000),seconds:Math.floor(diff%60000/1000)}}
  function countdownCells(c){return [['Dage','days'],['Timer','hours'],['Min','minutes'],['Sek','seconds']].map(([l,k])=>`<div class="countdown-cell"><strong data-countdown-${k}>${pad(c[k])}</strong><span>${l}</span></div>`).join('')}
  function updateLiveDisplays(){const c=countdownInfo();Object.entries(c).forEach(([k,v])=>qsa(`[data-countdown-${k}]`).forEach(el=>el.textContent=pad(v)));const now=new Date();qsa('[data-live-time]').forEach(el=>el.textContent=now.toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'}));qsa('[data-live-date]').forEach(el=>el.textContent=now.toLocaleDateString('da-DK',{weekday:'long',day:'numeric',month:'long',year:'numeric'}));qsa('[data-live-weather]').forEach(el=>el.textContent=state.settings.clock.showWeather?weather.summary:'Vejrvisning er slået fra');qsa('[data-live-location]').forEach(el=>el.textContent=weather.location)}
  async function refreshWeather(force=false){if(!state.settings.clock.showWeather)return updateLiveDisplays();if(!force&&weather.fetchedAt&&Date.now()-weather.fetchedAt<20*60*1000)return;weather.summary='Henter vejret…';updateLiveDisplays();const pos=state.settings.clock.useLocation?await getCurrentPosition():null;const fallback=state.campsites.find(s=>Number(s.lat)&&Number(s.lng));const coords=pos||fallback&&{lat:Number(fallback.lat),lng:Number(fallback.lng)};weather.coords=coords||null;if(!coords){weather.summary='Placering ikke tilgængelig';weather.location='Aktuel placering';return updateLiveDisplays()}try{const res=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${coords.lat}&longitude=${coords.lng}&current=temperature_2m,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min&timezone=auto`);const j=await res.json();const cur=j.current||{};const min=j.daily?.temperature_2m_min?.[0],max=j.daily?.temperature_2m_max?.[0];weather.summary=`${Math.round(cur.temperature_2m||0)}°C · ${weatherLabel(cur.weather_code)} · vind ${Math.round(cur.wind_speed_10m||0)} km/t · ${Math.round(min||0)}°/${Math.round(max||0)}°`;weather.location=pos?'Aktuel placering':countryLine(fallback);weather.fetchedAt=Date.now()}catch(e){weather.summary='Vejret kunne ikke hentes';weather.location='Aktuel placering'}updateLiveDisplays()}
  function weatherLabel(c){return ({0:'solrigt',1:'mest klart',2:'let skyet',3:'overskyet',45:'tåget',51:'støvregn',61:'let regn',63:'regn',65:'kraftig regn',71:'sne',80:'byger',95:'torden'})[Number(c)]||'skiftende vejr'}
  function getCurrentPosition(){return new Promise(resolve=>{if(!navigator.geolocation)return resolve(null);navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),()=>resolve(null),{enableHighAccuracy:true,timeout:9000,maximumAge:300000})})}

  function stats(){const visited=state.campsites.filter(s=>s.status==='visited');return {visited:visited.length,wish:state.campsites.filter(s=>s.status==='wish').length,countries:new Set(visited.map(s=>s.country).filter(Boolean)).size,routes:state.routes.length}}
  function sortedVisited(sort){return sortCampsites(state.campsites.filter(s=>s.status==='visited'),sort)}
  function sortCampsites(arr,sort){const a=[...arr];if(sort==='name')return a.sort((x,y)=>x.name.localeCompare(y.name,'da'));if(sort==='rating')return a.sort((x,y)=>averageRating(y)-averageRating(x));return a.sort((x,y)=>String(latestDate(y)).localeCompare(String(latestDate(x))))}
  function averageRating(s){const vals=Object.values(s.ratings||{}).map(Number).filter(v=>v>0);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0}
  function latestDate(s){return (s.visitDates||[]).slice().sort().at(-1)||s.plannedDate||''}
  function countryLine(s){return [s.city,s.region,s.country].filter(Boolean).join(', ')}
  function parseCoordinate(v){const n=Number(String(v).replace(',','.'));return Number.isFinite(n)?n:''}
  function parseAttractions(text){return lines(text).map(line=>{const [name='',description='',link='']=line.split('|').map(x=>x.trim());return {name,description,link}})}
  function getCampsite(id){return state.campsites.find(x=>x.id===id)}function getRoute(id){return state.routes.find(x=>x.id===id)}function getBike(id){return state.bikes.find(x=>x.id===id)}function getPerson(id){return state.people.find(x=>x.id===id)}
  function moveItem(arr,index,delta){const to=index+delta;if(to<0||to>=arr.length)return;[arr[index],arr[to]]=[arr[to],arr[index]];saveState();renderApp()}
  function setIconPath(path,src){if(path.startsWith('quick.'))state.settings.icons.quick[path.split('.')[1]]=src;else state.settings.icons[path]=src}
  function exportBackup(){const copy=structuredClone(state);const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'});downloadBlob(blob,`vores-camping-backup-${new Date().toISOString().slice(0,10)}.json`);toast('Backup eksporteret.')}
  async function importBackup(e){const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());state=normalizeState(data);saveState();applyTheme();renderApp();toast('Backup importeret.')}catch(error){toast('Backupfilen kunne ikke læses.')}}
  function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  async function compressImage(file,max=1280,quality=.78){if(!file)return'';if(file.type==='image/svg+xml')return file.text().then(t=>'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(t))));const bitmap=await createImageBitmap(file);const ratio=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',quality)}
  function uniqueBy(arr,keyFn){const set=new Set();return arr.filter(x=>{const k=keyFn(x);if(set.has(k))return false;set.add(k);return true})}
  function daysSince(date){if(!date)return 0;return Math.max(1,Math.floor((Date.now()-new Date(date))/86400000)+1)}
  function toLocalInput(v){if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v).slice(0,16);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
  function lines(v){return String(v||'').split(/\n+/).map(x=>x.trim()).filter(Boolean)}function csv(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}
  function firstName(v){return String(v||'').trim().split(/\s+/)[0]||''}function pad(v){return String(v).padStart(2,'0')}function uid(prefix='id'){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`}
  function formatDate(v){if(!v)return'';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString('da-DK',{day:'numeric',month:'short',year:'numeric'})}
  function esc(v=''){return String(v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}function safeUrl(v=''){try{const u=new URL(v,location.href);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch(_){return'#'}}
  function empty(text){return `<div class="empty">${esc(text)}</div>`}function qs(sel,root=document){return root.querySelector(sel)}function qsa(sel,root=document){return [...root.querySelectorAll(sel)]}
  function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;qs('#toast-host').appendChild(el);setTimeout(()=>el.remove(),3200)}
  function setBusy(btn,busy,text){if(!btn)return;btn.disabled=busy;btn.textContent=text}
  function confirmAction(title,text){const dialog=qs('#confirm-dialog');qs('#confirm-title').textContent=title;qs('#confirm-text').textContent=text;dialog.showModal();return new Promise(resolve=>dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true}))}
  function shareText(title,url){if(navigator.share)navigator.share({title,url}).catch(()=>{});else navigator.clipboard?.writeText(url).then(()=>toast('Link kopieret.'))}
  function showFatal(error){console.error(error);const el=qs('#error-boundary');el.classList.remove('hidden');el.innerHTML=`<strong>Appen ramte en fejl.</strong><p>${esc(error?.message||String(error))}</p><button class="ghost-btn" onclick="location.reload()">Genindlæs</button>`}function clearFatal(){qs('#error-boundary').classList.add('hidden')}
})();
